/**
 * FoodShareAI - AI Analysis Model
 * Stores inference results generated by our custom ML vision/freshness models (PyTorch/TensorFlow).
 * Architecture designed for standalone Python ML microservice integration.
 */
const mongoose = require('mongoose');
const { FRESHNESS_STATUS } = require('../utils/constants');

const foodDetectionItemSchema = new mongoose.Schema(
  {
    itemName: {
      type: String,
      required: true,
      trim: true,
    },
    category: {
      type: String,
      required: true,
      trim: true,
    },
    confidence: {
      type: Number,
      required: true,
      min: 0,
      max: 1,
    },
  },
  { _id: false }
);

const aiAnalysisSchema = new mongoose.Schema(
  {
    donationId: {
      type: mongoose.Schema.Types.ObjectId,
      ref: 'Donation',
      required: [true, 'Donation ID reference is required'],
      index: true,
    },
    modelVersion: {
      type: String,
      required: [true, 'Model version string is required'],
      default: 'food-classifier-v1',
      trim: true,
      index: true,
    },
    status: {
      type: String,
      enum: ['PENDING', 'PROCESSING', 'COMPLETED', 'FAILED', 'MODEL_NOT_LOADED'],
      default: 'COMPLETED',
      index: true,
    },
    modelsLoaded: {
      foodDetection: { type: Boolean, default: false },
      freshness: { type: Boolean, default: false },
      quantity: { type: Boolean, default: false },
      expiry: { type: Boolean, default: false },
    },
    foodDetection: [foodDetectionItemSchema],
    freshnessPrediction: {
      label: {
        type: String,
        enum: {
          values: [
            FRESHNESS_STATUS.UNKNOWN,
            FRESHNESS_STATUS.FRESH,
            FRESHNESS_STATUS.GOOD,
            FRESHNESS_STATUS.MODERATE,
            FRESHNESS_STATUS.EXPIRING,
            FRESHNESS_STATUS.UNSAFE,
          ],
          message: '{VALUE} is not a recognized freshness classification',
        },
        default: FRESHNESS_STATUS.UNKNOWN,
      },
      confidence: {
        type: Number,
        min: 0,
        max: 1,
        default: 0,
      },
    },
    quantityEstimation: {
      value: {
        type: Number,
        min: 0,
        default: 0,
      },
      unit: {
        type: String,
        default: 'KG',
      },
      confidence: {
        type: Number,
        min: 0,
        max: 1,
        default: 0,
      },
    },
    expiryPrediction: {
      estimatedSafeHours: {
        type: Number,
        min: 0,
        default: 0,
      },
      estimatedExpiryTime: {
        type: Date,
        default: null,
      },
      riskLevel: {
        type: String,
        default: 'SAFE',
      },
      disclaimer: {
        type: String,
        default: '',
      },
    },
    confidence: {
      overall: {
        type: Number,
        min: 0,
        max: 1,
        default: 0,
      },
    },
    processingTime: {
      type: Number, // Model inference time in milliseconds
      min: 0,
      default: 0,
    },
    imageMetadata: {
      format: { type: String, default: '' },
      dimensions: {
        width: { type: Number, default: 0 },
        height: { type: Number, default: 0 },
      },
      sizeBytes: { type: Number, default: 0 },
    },
  },
  {
    timestamps: true,
  }
);

aiAnalysisSchema.index({ donationId: 1, createdAt: -1 });

const AIAnalysis = mongoose.model('AIAnalysis', aiAnalysisSchema);

module.exports = AIAnalysis;
